{
  "findings": [
    {
      "ref": "[D502]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default until an age check is completed.",
      "stance": "risk",
      "quote": "You must complete an age check before using Communication Features."
    },
    {
      "ref": "[D502]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases of Robux that can be used to buy items, and purchases are non-refundable and may be revoked without notice.",
      "stance": "risk",
      "quote": "Robux may not be purchased, used, sold, distributed, or otherwise used, except through channels and mechanisms made available or otherwise approved by Roblox."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that Roblox may collect and review user-generated content and communication content for moderation, and may share data with third parties for legal or safety reasons.",
      "stance": "risk",
      "quote": "Roblox may access and review Content, including Content shared via Communication Features and other non-public Content."
    },
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate for communication features is not effective in practice, as users can bypass it or the system does not enforce it consistently.",
      "stance": "neutral",
      "quote": "You must complete an age check before using Communication Features."
    },
    {
      "ref": "[D502]",
      "area": "content",
      "claim": "A parent reports that the platform contains user-generated content that may include inappropriate language, images, or experiences, and moderation may be delayed or omitted.",
      "stance": "risk",
      "quote": "Roblox has the right, but not the obligation, to monitor, review, modify, disable access to, or remove any UGC or other Content on the Services, in whole or in part, at any time, with or without notice, and without liability to you or any third party."
    },
    {
      "ref": "[D502]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data collection and child safety failures.",
      "stance": "risk",
      "quote": "Roblox may delay or omit a notice where we reasonably believe that notifying you would breach the law or the direction of an authority or court or would otherwise risk legal liability for Roblox."
    }
  ]
}
